function countHiddenWords(text: string, words: string[]): number {
  let count = 0;
  for (const w of words) {
    let i = 0;
    for (let t = 0; t < text.length && i < w.length; t++) if (text[t] === w[i]) i++;
    if (i === w.length) count++;
  }
  return count;
}

