function countHiddenWords(text: string, words: string[]): number {
  const pos: number[][] = Array.from({ length: 26 }, () => []);
  for (let i = 0; i < text.length; i++) pos[text.charCodeAt(i) - 97].push(i);
  let count = 0;
  for (const w of words) {
    let at = -1, ok = true;
    for (const ch of w) {
      const list = pos[ch.charCodeAt(0) - 97];
      let lo = 0, hi = list.length;
      while (lo < hi) { const mid = (lo + hi) >> 1; if (list[mid] <= at) lo = mid + 1; else hi = mid; }
      if (lo === list.length) { ok = false; break; }
      at = list[lo];
    }
    if (ok) count++;
  }
  return count;
}

