function countHiddenWords(text: string, words: string[]): number {
  // each entry is [wordIndex, position of the next needed letter]
  let buckets: [number, number][][] = Array.from({ length: 26 }, () => []);
  words.forEach((w, i) => buckets[w.charCodeAt(0) - 97].push([i, 0]));
  let count = 0;
  for (let t = 0; t < text.length; t++) {
    const c = text.charCodeAt(t) - 97;
    const waiting = buckets[c];
    buckets[c] = [];
    for (const [wi, p] of waiting) {
      const w = words[wi];
      if (p + 1 === w.length) count++;
      else buckets[w.charCodeAt(p + 1) - 97].push([wi, p + 1]);
    }
  }
  return count;
}

