class Solution:
    def countHiddenWords(self, text: str, words: List[str]) -> int:
        buckets = defaultdict(list)  # letter -> list of (word index, next position)
        for i, w in enumerate(words):
            buckets[w[0]].append((i, 0))
        count = 0
        for c in text:
            waiting = buckets.pop(c, [])
            for wi, p in waiting:
                w = words[wi]
                if p + 1 == len(w):
                    count += 1
                else:
                    buckets[w[p + 1]].append((wi, p + 1))
        return count

